output_text:
[
  {
    "id": "take_cart_from_bay",
    "text": "A shopper is obliged to take a cart from the cart bay before doing the trip.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)"
      },
      "events": {
        "takeCartAtBay": {
          "pre": {
            "and": [
              "cartBay",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeCartAtBay"
    }
  },
  {
    "id": "no_cart_in_narrow_shelf_aisle",
    "text": "Carts are prohibited in the narrow shelf aisles where shelves flank both sides.",
    "abstraction": {
      "state_properties": {
        "narrowShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "narrowShelfAisle"
        ]
      }
    }
  },
  {
    "id": "park_before_hand_aisle",
    "text": "A shopper with a cart is prohibited from moving north from an aisle mouth into a hand-only narrow aisle.",
    "abstraction": {
      "state_properties": {
        "handAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "driveNorthFromMouth": {
          "pre": {
            "and": [
              "handAisleMouth",
              "hasCart",
              "N"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "driveNorthFromMouth"
    }
  },
  {
    "id": "drop_cart_only_at_mouths",
    "text": "A cart may only be left behind at designated wide aisle-mouth parking spots.",
    "abstraction": {
      "state_properties": {
        "designatedCartPark": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "designatedCartPark"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart to enter a hand-only aisle, the shopper is obliged to retrieve the cart before the trip ends.",
    "abstraction": {
      "state_properties": {
        "designatedCartPark": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCartAtPark": {
          "pre": {
            "and": [
              "designatedCartPark",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtPark": {
          "pre": {
            "and": [
              "designatedCartPark",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCartAtPark",
      "discharge": "retrieveCartAtPark"
    }
  },
  {
    "id": "cart_required_for_wide_shelf_service",
    "text": "Interacting with shelves from cart-accessible wide areas is prohibited unless the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "narrowShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "wideShelfServiceArea": {
          "and": [
            "adjShelf",
            {
              "not": "narrowShelfAisle"
            }
          ]
        }
      },
      "events": {
        "wideShelfInteract": {
          "pre": {
            "and": [
              "wideShelfServiceArea",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideShelfInteract",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_traffic_no_west",
    "text": "When pushing a cart, westward movement against the store traffic flow is prohibited.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartWestMove": {
          "pre": {
            "and": [
              "hasCart",
              "W"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartWestMove"
    }
  },
  {
    "id": "return_to_front_exit_lane_after_wide_shelf",
    "text": "After serving a shelf from a cart-accessible area, the shopper is obliged to rejoin the front exit lane with the cart.",
    "abstraction": {
      "state_properties": {
        "narrowShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "wideShelfServiceArea": {
          "and": [
            "adjShelf",
            {
              "not": "narrowShelfAisle"
            }
          ]
        },
        "frontExitLaneWithCart": {
          "and": [
            "hasCart",
            {
              "or": [
                "at(6,7)",
                "at(7,7)",
                "at(8,7)",
                "at(9,7)",
                "at(10,7)",
                "at(11,7)"
              ]
            }
          ]
        }
      },
      "events": {
        "wideShelfPickup": {
          "pre": {
            "and": [
              "wideShelfServiceArea",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "wideShelfPickup",
      "discharge": "frontExitLaneWithCart"
    }
  }
]
